import{_ as i,C as s,o as h,c as d,j as t,a as o,E as r,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const y=JSON.parse('{"title":"Set up the review bot","description":"","frontmatter":{},"headers":[],"relativePath":"review-bot/setup.md","filePath":"review-bot/setup.md"}'),c={name:"review-bot/setup.md"};function u(g,e,p,b,w,k){const n=s("Badge"),a=s("Shot");return h(),d("div",null,[e[0]||(e[0]=t("h1",{id:"set-up-the-review-bot",tabindex:"-1"},[o("Set up the review bot "),t("a",{class:"header-anchor",href:"#set-up-the-review-bot","aria-label":'Permalink to "Set up the review bot"'},"​")],-1)),r(n,{type:"built",text:"Built"}),e[1]||(e[1]=o(" The bot is off until a Workspace admin or owner switches it on for a repository.",-1)),e[2]||(e[2]=t("h2",{id:"before-you-start",tabindex:"-1"},[o("Before you start "),t("a",{class:"header-anchor",href:"#before-you-start","aria-label":'Permalink to "Before you start"'},"​")],-1)),r(a,{src:"/shots/member-profile.png",alt:"My settings › Profile with the Linked accounts card and the coding engine choice",caption:"My settings › Profile: link your Git host account so the bot knows who comments."}),e[3]||(e[3]=l('<ul><li>The repository is in the Workspace, through a <strong>GitHub</strong>, <strong>GitLab</strong> or <strong>Bitbucket</strong> connection. See <a href="/docs/connections/">Connections</a> and <a href="/docs/work/git">Git and pull requests</a>.</li><li>The connection may write pull request comments. The bot reads the change through a read-only checkout and posts through the connection&#39;s governed tools.</li><li>People who want to use <a href="/docs/review-bot/commands">commands</a> link their host account to Octryx AI under <strong>My settings › Profile</strong>, card <strong>Linked accounts</strong>.</li></ul><h2 id="_1-switch-it-on-for-a-repository" tabindex="-1">1. Switch it on for a repository <a class="header-anchor" href="#_1-switch-it-on-for-a-repository" aria-label="Permalink to &quot;1. Switch it on for a repository&quot;">​</a></h2><p>Open <strong>Admin › Workspaces</strong>, choose the Workspace, then <strong>Workspace settings › Data › Repositories</strong>. Below the list of repositories, the section <strong>PR review bot</strong> has one card per GitHub, GitLab or Bitbucket repository.</p><p>Under <strong>Review pull requests</strong>, choose:</p><table tabindex="0"><thead><tr><th>Option</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Off</strong></td><td>Nothing is reviewed or posted on this repository.</td></tr><tr><td><strong>On every push (webhook)</strong></td><td>Each pull request event starts a review; the bot waits up to 90 seconds for a newer push first.</td></tr><tr><td><strong>Hourly sync</strong></td><td>Open pull requests are checked once an hour.</td></tr><tr><td><strong>Webhook and hourly sync</strong> (recommended)</td><td>Reviews at once; the hourly sync catches what a webhook missed.</td></tr></tbody></table><p>Choose the <a href="/docs/review-bot/settings#status-on-the-pull-request">status</a>, then <strong>Save</strong>. <strong>Sync now</strong> runs the sync at once; it needs <strong>Hourly sync</strong> or <strong>Webhook and hourly sync</strong>, saved.</p><p>A local installation that the host cannot reach uses <strong>Hourly sync</strong>. Pull requests opened by Octryx AI&#39;s own runs are picked up within about 5 seconds either way.</p><h2 id="_2-add-the-pull-request-webhook" tabindex="-1">2. Add the pull request webhook <a class="header-anchor" href="#_2-add-the-pull-request-webhook" aria-label="Permalink to &quot;2. Add the pull request webhook&quot;">​</a></h2><p>For <strong>On every push</strong> and <strong>Webhook and hourly sync</strong>, the Workspace needs one pull request webhook:</p><ol><li>Open <strong>Admin › Webhooks</strong> and create a webhook with the source <strong>Pull request (GitHub, GitLab, Bitbucket)</strong>.</li><li><strong>The sending tool can&#39;t sign a timestamp</strong> is ticked and locked for this source: GitHub, GitLab and Bitbucket send no timestamp. Repeats of the same call within 5 minutes are still refused.</li><li>Copy the address and the secret. The secret is shown only once, in the screen and in the API, when the webhook is created or the secret is rotated.</li><li>Add the webhook in your Git host, as below.</li></ol><p>The PR review bot card then says &quot;The Workspace&#39;s pull request webhook is set up.&quot;</p><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub&quot;">​</a></h3><p><strong>Repository › Settings › Webhooks › Add webhook</strong>: the address as <strong>Payload URL</strong>, content type <code>application/json</code>, the secret as <strong>Secret</strong>. Choose the events <strong>Pull requests</strong>, <strong>Issue comments</strong> and <strong>Pull request review comments</strong>.</p><h3 id="gitlab" tabindex="-1">GitLab <a class="header-anchor" href="#gitlab" aria-label="Permalink to &quot;GitLab&quot;">​</a></h3><p><strong>Project › Settings › Webhooks</strong>: the address as <strong>URL</strong>, the secret as <strong>Secret token</strong>. Tick <strong>Merge request events</strong> and <strong>Comments</strong>.</p><h3 id="bitbucket" tabindex="-1">Bitbucket <a class="header-anchor" href="#bitbucket" aria-label="Permalink to &quot;Bitbucket&quot;">​</a></h3><ul><li><strong>Cloud</strong>: <strong>Repository settings › Webhooks</strong>, with the triggers <strong>Pull request: Created</strong>, <strong>Updated</strong> and <strong>Comment created</strong>.</li><li><strong>Server and Data Center</strong>: <strong>Repository settings › Webhooks</strong>, with the events <strong>Opened</strong>, <strong>Source branch updated</strong> and <strong>Comment added</strong>, and the secret.</li></ul><h3 id="what-the-webhook-does" tabindex="-1">What the webhook does <a class="header-anchor" href="#what-the-webhook-does" aria-label="Permalink to &quot;What the webhook does&quot;">​</a></h3><ul><li>Only the sender&#39;s signature counts; a call with a wrong secret is refused.</li><li>A delivery that comes twice is refused the second time.</li><li>At most 120 calls per minute per webhook and sender.</li><li>A start waits 90 seconds for a newer push: if one comes, only the newest commit is reviewed.</li><li>A test call from the webhook screen starts nothing.</li></ul><h2 id="_3-check-it" tabindex="-1">3. Check it <a class="header-anchor" href="#_3-check-it" aria-label="Permalink to &quot;3. Check it&quot;">​</a></h2><p>Open a pull request. Within about 90 seconds (webhook) or at the next sync, the status <code>octryx/review</code> (GitHub) or <code>octryx-review</code> (GitLab, Bitbucket) shows <strong>pending</strong>, then the summary comment appears.</p><h2 id="what-is-never-reviewed" tabindex="-1">What is never reviewed <a class="header-anchor" href="#what-is-never-reviewed" aria-label="Permalink to &quot;What is never reviewed&quot;">​</a></h2><ul><li>pull requests from forks;</li><li>drafts, unless <strong>Review drafts</strong> is on; a draft is reviewed once it is ready for review;</li><li>a commit that was already reviewed (use <code>@octryx review full</code> to review it again);</li><li>pull requests on which someone wrote <code>@octryx pause</code>.</li></ul>',23))])}const f=i(c,[["render",u]]);export{y as __pageData,f as default};
